import { useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Link, Route, Router as WouterRouter, Switch, useLocation, useRoute } from 'wouter';
import { QueryClient, QueryClientProvider, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { BarChart3, Check, ChevronRight, Database, Leaf, Menu, RefreshCw, Satellite, Sprout, X } from 'lucide-react';
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { FieldTwin } from '@/components/agritwin/FieldTwin';
import { api, type ApiHealth, type DailyState, type Field, type Simulation } from '@/api/client';

const queryOptions = { retry: false, staleTime: 30_000 };
const nav = [
  { label: 'Overview', href: '/' }, { label: 'Fields', href: '/fields' },
  { label: 'Simulations', href: '/simulations' }, { label: 'Assimilation', href: '/assimilation' },
  { label: 'Observations', href: '/observations' }, { label: 'Forecast', href: '/forecast' },
  { label: 'Scenarios', href: '/scenarios' }, { label: 'Research', href: '/benchmark' },
];
const compactNav = [{ label: 'Satellite', href: '/satellite' }, { label: 'Fusion', href: '/fusion' }, { label: 'Scout', href: '/scout' }, { label: 'About', href: '/about' }];

function Shell({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const health = useQuery({ queryKey: ['health'], queryFn: api.health, ...queryOptions, refetchInterval: 60_000 });
  return <div className="min-h-screen bg-[#faf9f6] text-[#1b3022]">
    <header className="sticky top-0 z-40 border-b border-[#dfe3dc] bg-[#faf9f6]/95 backdrop-blur">
      <div className="mx-auto flex h-[68px] max-w-[1400px] items-center justify-between px-5 sm:px-8">
        <Link href="/" className="flex items-center gap-3" onClick={() => setOpen(false)}>
          <span className="flex h-8 w-8 items-center justify-center bg-[#1b3022] text-[#faf9f6]"><Leaf size={16} /></span>
          <span className="font-semibold tracking-[-.04em]">AgriTwin</span><span className="mono border-l border-[#d9ded7] pl-3 text-[9px] text-[#7d857f]">v0.2</span>
        </Link>
        <nav className="hidden items-center gap-5 xl:flex">{nav.slice(0, 6).map((item) => <NavLink key={item.href} item={item} />)}</nav>
        <div className="hidden items-center gap-4 md:flex">
          <HealthBadge health={health} />
          <Link href="/fields" className="bg-[#1b3022] px-4 py-2.5 text-[11px] font-semibold text-white hover:bg-[#2d4935]">Open platform <ChevronRight size={13} className="ml-1 inline" /></Link>
        </div>
        <button className="p-2 md:hidden" onClick={() => setOpen(!open)} aria-label="Toggle navigation">{open ? <X size={20} /> : <Menu size={20} />}</button>
      </div>
      {open && <nav className="border-t border-[#dfe3dc] bg-[#faf9f6] px-5 py-3 md:hidden">{[...nav, ...compactNav].map((item) => <NavLink key={item.href} item={item} onClick={() => setOpen(false)} />)}<div className="border-t border-[#dfe3dc] py-3"><HealthBadge health={health} /></div></nav>}
    </header>
    <main>{children}</main>
    <footer className="border-t border-[#36503c] bg-[#1b3022] text-[#e8efe6]"><div className="mx-auto flex max-w-[1400px] flex-col gap-8 px-5 py-10 sm:flex-row sm:items-end sm:justify-between sm:px-8"><div><div className="flex items-center gap-3"><Leaf size={16} /><span className="font-semibold">AgriTwin</span></div><p className="mt-3 max-w-[330px] text-xs leading-5 text-[#aab9aa]">Physics-based crop simulation with real-world observations and sequential data assimilation.</p></div><div className="flex flex-wrap gap-x-5 gap-y-2 text-xs text-[#b9c6ba]">{compactNav.map((item) => <Link key={item.href} href={item.href}>{item.label}</Link>)}</div></div></footer>
  </div>;
}
function NavLink({ item, onClick }: { item: { label: string; href: string }; onClick?: () => void }) { return <Link href={item.href} onClick={onClick} className="block py-2 text-[12px] text-[#68716a] hover:text-[#1b3022]">{item.label}</Link>; }
function HealthBadge({ health }: { health: { isLoading: boolean; isError: boolean; data?: unknown } }) {
  const label = health.isLoading ? 'CHECKING API' : health.isError ? 'API OFFLINE' : 'API CONNECTED';
  const data = health.data as ApiHealth | undefined;
  return <span className="flex items-center gap-2 text-[10px] text-[#69736c]"><span className={`h-1.5 w-1.5 rounded-full ${health.isError ? 'bg-[#b76a3d]' : health.isLoading ? 'bg-[#d97706]' : 'bg-[#6f9771]'}`} />{label}{data?.database && <span className="text-[#9aa39b]">· DB {data.database}</span>}</span>;
}
function Page({ eyebrow, title, description, children }: { eyebrow: string; title: string; description?: string; children: ReactNode }) { return <section className="mx-auto max-w-[1400px] px-5 py-12 sm:px-8 sm:py-16"><div className="mb-10 border-b border-[#dfe3dc] pb-7"><p className="label-caps text-[#6b866b]">{eyebrow}</p><h1 className="mt-3 max-w-4xl text-4xl font-semibold tracking-[-.065em] text-[#1b3022] sm:text-5xl">{title}</h1>{description && <p className="mt-4 max-w-2xl text-sm leading-6 text-[#657067]">{description}</p>}</div>{children}</section>; }
function Panel({ children, className = '' }: { children: ReactNode; className?: string }) { return <div className={`border border-[#dfe3dc] bg-white ${className}`}>{children}</div>; }
function StateMessage({ title, error, onRetry }: { title: string; error?: Error; onRetry?: () => void }) { return <div className="border border-[#e0e4dc] bg-[#f0f3ed] p-8 text-center"><p className="text-sm font-semibold">{title}</p>{error && <p className="mt-2 text-xs text-[#7a827b]">{error.message === 'Failed to fetch' ? 'Backend API unavailable.' : error.message}</p>}{onRetry && <button onClick={onRetry} className="mt-4 inline-flex items-center gap-2 border border-[#1b3022] px-3 py-2 text-xs font-semibold"><RefreshCw size={13} /> Retry</button>}</div>; }
function Loading() { return <div className="border border-[#dfe3dc] bg-white p-10 text-center text-xs text-[#788078]"><RefreshCw size={15} className="mx-auto mb-3 animate-spin" />Loading backend data…</div>; }
function Metric({ label, value, unit }: { label: string; value: string | number | null | undefined; unit?: string }) { return <div className="border border-[#e1e4de] bg-white p-5"><p className="label-caps text-[#69736c]">{label}</p><p className="mono mt-5 text-2xl text-[#1b3022]">{value === null || value === undefined ? '—' : value}</p>{unit && <p className="mt-1 text-[11px] text-[#788078]">{unit}</p>}</div>; }
function formatDate(value?: string | null) { return value ? new Date(value).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) : '—'; }
function lastState(states?: DailyState[]) { return states?.length ? states[states.length - 1] : undefined; }

function OverviewPage() {
  const fields = useQuery({ queryKey: ['fields', 'overview'], queryFn: () => api.fields(), ...queryOptions });
  const sims = useQuery({ queryKey: ['simulations', 'overview'], queryFn: () => api.simulations(), ...queryOptions });
  const observations = useQuery({ queryKey: ['observations', 'overview'], queryFn: () => api.observations(), ...queryOptions });
  const latest = sims.data?.items[0];
  const status = useQuery({ queryKey: ['assimilation-status', latest?.simulation_id], queryFn: () => api.assimilationStatus(latest!.simulation_id), enabled: Boolean(latest), ...queryOptions });
  return <><section className="mx-auto max-w-[1400px] px-5 pb-14 pt-16 text-center sm:px-8 sm:pt-24"><p className="label-caps text-[#6b866b]">AGRICULTURAL DIGITAL TWIN</p><h1 className="mx-auto mt-6 max-w-4xl text-5xl font-semibold leading-[.98] tracking-[-.075em] sm:text-7xl">A Digital Twin for Every Field.</h1><p className="mx-auto mt-7 max-w-2xl text-base leading-7 text-[#5e675f]">AgriTwin combines physics-based crop simulation, real-world observations and sequential data assimilation to understand field conditions and forecast what happens next.</p><div className="mt-8 flex justify-center gap-3"><Link href="/fields" className="bg-[#1b3022] px-5 py-3.5 text-xs font-semibold text-white">Explore the platform <ChevronRight size={14} className="ml-2 inline" /></Link><Link href="/about" className="border border-[#1b3022] px-5 py-3.5 text-xs font-semibold">How it works <ChevronRight size={14} className="ml-2 inline" /></Link></div></section><section className="bg-[#f0f3ed] px-5 py-12 sm:px-8 sm:py-16"><div className="mx-auto max-w-[1400px]"><div className="mb-7 flex items-end justify-between"><div><p className="label-caps text-[#6b866b]">LIVE PLATFORM OVERVIEW</p><h2 className="mt-2 text-2xl font-semibold tracking-[-.05em]">Field intelligence, from the API.</h2></div><HealthBadge health={fields} /></div>{fields.isLoading || sims.isLoading || observations.isLoading ? <Loading /> : fields.isError || sims.isError || observations.isError ? <StateMessage title="Unable to load platform summary." error={(fields.error || sims.error || observations.error) as Error} onRetry={() => { fields.refetch(); sims.refetch(); observations.refetch(); }} /> : <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Fields" value={fields.data?.total} unit="API records" /><Metric label="Simulations" value={sims.data?.total} unit="API records" /><Metric label="Observations" value={observations.data?.total} unit="API records" /><Metric label="Latest assimilation" value={status.data?.status || (latest ? 'No run' : '—')} unit={latest ? `Simulation ${latest.simulation_id.slice(0, 8)}…` : 'No simulation available'} /></div>}</div></section><section className="mx-auto grid max-w-[1400px] gap-3 px-5 py-14 sm:grid-cols-2 sm:px-8 lg:grid-cols-5">{[['Fields', '/fields', 'Browse field records and open a digital twin.'], ['Simulations', '/simulations', 'Review stored WOFOST/PCSE runs.'], ['Assimilation', latest ? `/assimilation/${latest.simulation_id}` : '/assimilation', 'Inspect EnKF cycles and state updates.'], ['Observations', '/observations', 'Explore source observations and quality.'], ['Scenarios', '/scenarios', 'Compare explicit model scenarios.']].map(([title, href, detail]) => <Link key={href} href={href} className="border border-[#dfe3dc] bg-white p-5 transition hover:-translate-y-0.5 hover:border-[#9bb49d]"><p className="label-caps text-[#6b866b]">OPEN</p><h3 className="mt-5 font-semibold">{title}</h3><p className="mt-2 text-xs leading-5 text-[#788078]">{detail}</p><ChevronRight size={15} className="mt-5 text-[#6b866b]" /></Link>)}</section></>;
}

function FieldsPage() {
  const qc = useQueryClient(); const [filters, setFilters] = useState({ farm_id: '', lat_min: '', lat_max: '', lon_min: '', lon_max: '' }); const [createOpen, setCreateOpen] = useState(false);
  const query = useQuery({ queryKey: ['fields', filters], queryFn: () => api.fields(filters), ...queryOptions });
  const create = useMutation({ mutationFn: api.createField, onSuccess: () => { qc.invalidateQueries({ queryKey: ['fields'] }); setCreateOpen(false); } });
  const remove = useMutation({ mutationFn: api.deleteField, onSuccess: () => qc.invalidateQueries({ queryKey: ['fields'] }) });
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); create.mutate({ name: data.get('name'), latitude: Number(data.get('latitude')), longitude: Number(data.get('longitude')), area_ha: data.get('area_ha') ? Number(data.get('area_ha')) : null, elevation_m: data.get('elevation_m') ? Number(data.get('elevation_m')) : null, description: data.get('description') || null }); };
  return <Page eyebrow="01 / FIELD REGISTRY" title="Fields" description="GPS-located agricultural plots grouped by the simulations and observations they contain."><div className="mb-6 flex flex-wrap justify-between gap-3"><div className="flex flex-wrap gap-2">{(['lat_min', 'lat_max', 'lon_min', 'lon_max'] as const).map((key) => <input key={key} value={filters[key]} onChange={(e) => setFilters({ ...filters, [key]: e.target.value })} placeholder={key.replace('_', ' ')} className="w-28 border border-[#dfe3dc] bg-white px-3 py-2 text-xs" />)}</div><button onClick={() => setCreateOpen(!createOpen)} className="bg-[#1b3022] px-4 py-2.5 text-xs font-semibold text-white">+ Create field</button></div>{createOpen && <Panel className="mb-5 p-5"><form onSubmit={submit} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{[['name', 'Field name'], ['latitude', 'Latitude'], ['longitude', 'Longitude'], ['area_ha', 'Area (ha)'], ['elevation_m', 'Elevation (m)'], ['description', 'Description']].map(([name, label]) => <label key={name} className="text-xs text-[#69736c]">{label}<input required={['name', 'latitude', 'longitude'].includes(name)} name={name} className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5 text-sm" /></label>)}<button disabled={create.isPending} className="bg-[#1b3022] px-4 py-2 text-xs font-semibold text-white sm:col-span-2 lg:col-span-3">{create.isPending ? 'Creating…' : 'Save field'}</button>{create.error && <p className="text-xs text-[#a34f38]">{(create.error as Error).message}</p>}</form></Panel>}{query.isLoading ? <Loading /> : query.isError ? <StateMessage title="Unable to load fields." error={query.error as Error} onRetry={() => query.refetch()} /> : !query.data?.items.length ? <StateMessage title="No fields found." /> : <Panel><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left text-xs"><thead className="border-b border-[#dfe3dc] text-[#69736c]"><tr>{['Field', 'Coordinates', 'Area', 'Elevation', 'Simulations', ''].map((h) => <th key={h} className="px-5 py-4 font-medium">{h}</th>)}</tr></thead><tbody>{query.data?.items.map((field) => <tr key={field.field_id} className="border-b border-[#eef0eb] last:border-0"><td className="px-5 py-4"><Link href={`/fields/${field.field_id}`} className="font-semibold hover:underline">{field.name}</Link><p className="mt-1 text-[10px] text-[#89928a]">{field.field_id.slice(0, 12)}…</p></td><td className="mono px-5 py-4">{field.latitude.toFixed(4)}, {field.longitude.toFixed(4)}</td><td className="px-5 py-4">{field.area_ha ?? '—'} ha</td><td className="px-5 py-4">{field.elevation_m ?? '—'} m</td><td className="px-5 py-4">{field.simulation_count}</td><td className="px-5 py-4 text-right"><Link href={`/fields/${field.field_id}`} className="mr-4 font-semibold text-[#527358]">Open field twin</Link><button onClick={() => { if (window.confirm(`Delete ${field.name}? This is irreversible.`)) remove.mutate(field.field_id); }} className="text-[#a34f38]">Delete</button></td></tr>)}</tbody></table></div></Panel>}</Page>;
}

function FieldDetailPage({ id }: { id: string }) {
  const field = useQuery({ queryKey: ['field', id], queryFn: () => api.field(id), ...queryOptions }); const sims = useQuery({ queryKey: ['simulations', 'field', id], queryFn: () => api.simulations({ field_id: id }), ...queryOptions }); const [selected, setSelected] = useState('');
  const simulationId = selected || sims.data?.items[0]?.simulation_id; const detail = useQuery({ queryKey: ['simulation', simulationId], queryFn: () => api.simulation(simulationId!), enabled: Boolean(simulationId), ...queryOptions }); const state = lastState(detail.data?.daily_states);
  if (field.isLoading) return <Page eyebrow="FIELD DIGITAL TWIN" title="Loading field"><Loading /></Page>; if (field.isError || !field.data) return <Page eyebrow="FIELD DIGITAL TWIN" title="Field unavailable"><StateMessage title="Unable to load this field." error={field.error as Error} /></Page>;
  return <Page eyebrow="02 / FIELD DIGITAL TWIN" title={field.data.name} description={field.data.description || 'A field record connected to stored crop simulations and observations.'}><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_300px]"><div><Panel className="overflow-hidden"><FieldTwin state="current" /><div className="border-t border-[#dfe3dc] p-4 text-xs text-[#788078]">Visualization surface · illustrative spatial rendering. State values below are from the selected backend simulation.</div></Panel></div><aside className="space-y-4"><Panel className="p-5"><p className="label-caps text-[#69736c]">FIELD PROFILE</p><h2 className="mt-5 text-lg font-semibold">{field.data.name}</h2><div className="mt-5 space-y-3 border-y border-[#e1e4de] py-4 text-xs">{[['Coordinates', `${field.data.latitude}, ${field.data.longitude}`], ['Area', field.data.area_ha ? `${field.data.area_ha} ha` : '—'], ['Elevation', field.data.elevation_m ? `${field.data.elevation_m} m` : '—'], ['Simulations', field.data.simulation_count]].map(([key, value]) => <div key={key} className="flex justify-between gap-3"><span className="text-[#69736c]">{key}</span><span className="mono text-right">{value}</span></div>)}</div></Panel><Panel className="p-5"><label className="label-caps text-[#69736c]">SIMULATION SELECTOR<select value={selected} onChange={(e) => setSelected(e.target.value)} className="mt-3 w-full border border-[#dfe3dc] bg-white px-3 py-2 text-xs"><option value="">Select a run</option>{sims.data?.items.map((sim) => <option key={sim.simulation_id} value={sim.simulation_id}>{sim.crop} · {sim.status} · {sim.simulation_id.slice(0, 8)}</option>)}</select></label>{sims.isError && <p className="mt-3 text-xs text-[#a34f38]">Unable to load simulations.</p>}{simulationId && <div className="mt-4 flex gap-2"><Link href={`/simulations/${simulationId}`} className="border border-[#1b3022] px-3 py-2 text-[11px] font-semibold">Simulation detail</Link><Link href={`/assimilation/${simulationId}`} className="bg-[#1b3022] px-3 py-2 text-[11px] font-semibold text-white">Assimilation</Link></div>}</Panel></aside></div>{detail.isLoading && <div className="mt-5"><Loading /></div>}{detail.data && <div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Metric label="Latest LAI" value={state?.lai as number} unit="m²/m²" /><Metric label="Soil moisture" value={state?.sm as number} unit="cm³/cm³" /><Metric label="Biomass" value={state?.tagp as number} unit="kg/ha" /><Metric label="Development" value={state?.dvs as number} /><Metric label="Yield estimate" value={detail.data.yield_kg_ha} unit="kg/ha" /></div>}</Page>;
}

function SimulationForm({ onDone }: { onDone: (id: string) => void }) {
  const crops = useQuery({ queryKey: ['crops'], queryFn: api.crops, ...queryOptions }); const [crop, setCrop] = useState(''); const varieties = crop ? crops.data?.[crop] || [] : []; const run = useMutation({ mutationFn: api.simulate, onSuccess: (data) => { const id = data.simulation_id || data.simulation_id; if (id) onDone(id); } });
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const d = new FormData(event.currentTarget); run.mutate({ latitude: Number(d.get('latitude')), longitude: Number(d.get('longitude')), crop, variety: d.get('variety'), sowing_date: d.get('sowing_date'), harvest_date: d.get('harvest_date') || null, max_duration: Number(d.get('max_duration') || 365), irrigation_events: [], use_real_weather: true, use_real_soil: true }); };
  return <Panel className="p-5"><p className="label-caps text-[#69736c]">RUN NEW SIMULATION</p>{crops.isError ? <StateMessage title="Unable to load available crops." error={crops.error as Error} onRetry={() => crops.refetch()} /> : <form onSubmit={submit} className="mt-5 grid gap-3 sm:grid-cols-2">{[['latitude', 'Latitude'], ['longitude', 'Longitude'], ['sowing_date', 'Sowing date']].map(([name, label]) => <label key={name} className="text-xs text-[#69736c]">{label}<input required name={name} type={name.includes('date') ? 'date' : 'number'} step="any" className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label>)}<label className="text-xs text-[#69736c]">Crop<select required value={crop} onChange={(e) => setCrop(e.target.value)} className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option value="">Select crop</option>{Object.keys(crops.data || {}).map((name) => <option key={name}>{name}</option>)}</select></label><label className="text-xs text-[#69736c]">Variety<select required name="variety" className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option value="">Select variety</option>{varieties.map((name) => <option key={name}>{name}</option>)}</select></label><label className="text-xs text-[#69736c]">Harvest date (optional)<input name="harvest_date" type="date" className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label><button disabled={run.isPending} className="bg-[#1b3022] px-4 py-2.5 text-xs font-semibold text-white sm:col-span-2">{run.isPending ? 'Running simulation…' : 'Run simulation'}</button>{run.error && <p className="text-xs text-[#a34f38] sm:col-span-2">{(run.error as Error).message}</p>}</form>}</Panel>;
}

function SimulationsPage() {
  const [, navigate] = useLocation(); const [filters, setFilters] = useState({ crop: '', variety: '', status: '', run_type: '' }); const query = useQuery({ queryKey: ['simulations', filters], queryFn: () => api.simulations(filters), ...queryOptions });
  return <Page eyebrow="03 / SIMULATION HISTORY" title="Simulations" description="Stored WOFOST/PCSE runs, their configuration, status, and agronomic outputs."><SimulationForm onDone={(id) => navigate(`/simulations/${id}`)} /><div className="my-6 grid gap-2 sm:grid-cols-4">{Object.keys(filters).map((key) => <input key={key} value={filters[key as keyof typeof filters]} onChange={(e) => setFilters({ ...filters, [key]: e.target.value })} placeholder={key.replace('_', ' ')} className="border border-[#dfe3dc] bg-white px-3 py-2.5 text-xs" />)}</div>{query.isLoading ? <Loading /> : query.isError ? <StateMessage title="Unable to load simulations." error={query.error as Error} onRetry={() => query.refetch()} /> : !query.data?.items.length ? <StateMessage title="No simulations found." /> : <Panel><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-xs"><thead className="border-b border-[#dfe3dc] text-[#69736c]"><tr>{['Crop / variety', 'Date', 'Status', 'Run type', 'Yield', ''].map((h) => <th key={h} className="px-5 py-4 font-medium">{h}</th>)}</tr></thead><tbody>{query.data.items.map((sim) => <tr key={sim.simulation_id} className="border-b border-[#eef0eb]"><td className="px-5 py-4"><Link href={`/simulations/${sim.simulation_id}`} className="font-semibold">{sim.crop}</Link><p className="mt-1 text-[#788078]">{sim.variety}</p></td><td className="px-5 py-4">{formatDate(sim.sowing_date)}</td><td className="px-5 py-4"><span className="border border-[#cbd7c7] px-2 py-1 text-[10px]">{sim.status}</span></td><td className="px-5 py-4">{sim.run_type}</td><td className="mono px-5 py-4">{sim.yield_kg_ha ?? '—'} kg/ha</td><td className="px-5 py-4 text-right"><Link href={`/simulations/${sim.simulation_id}`} className="font-semibold text-[#527358]">Open detail <ChevronRight size={13} className="inline" /></Link></td></tr>)}</tbody></table></div></Panel>}</Page>;
}

function SimulationDetailPage({ id }: { id: string }) {
  const query = useQuery({ queryKey: ['simulation', id], queryFn: () => api.simulation(id), ...queryOptions }); const [variable, setVariable] = useState('lai'); const data = useMemo(() => query.data?.daily_states.filter((row) => typeof row[variable] === 'number').map((row) => ({ date: String(row.date), value: row[variable] })) || [], [query.data, variable]); const variables = query.data ? ['lai', 'sm', 'tagp', 'twso', 'rftra', 'dvs'].filter((key) => query.data.daily_states.some((row) => typeof row[key] === 'number')) : [];
  if (query.isLoading) return <Page eyebrow="SIMULATION DETAIL" title="Loading simulation"><Loading /></Page>; if (query.isError || !query.data) return <Page eyebrow="SIMULATION DETAIL" title="Simulation unavailable"><StateMessage title="Unable to load simulation detail." error={query.error as Error} /></Page>;
  return <Page eyebrow="04 / SIMULATION DETAIL" title={`${query.data.crop} · ${query.data.variety}`} description="Daily state time series returned by the simulation endpoint. Values are shown without silently changing backend units."><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Metric label="Status" value={query.data.status} /><Metric label="Sowing date" value={formatDate(query.data.sowing_date)} /><Metric label="Harvest date" value={formatDate(query.data.harvest_date)} /><Metric label="Yield" value={query.data.yield_kg_ha} unit="kg/ha" /><Metric label="Peak LAI" value={query.data.peak_lai} unit="m²/m²" /></div><Panel className="mt-5 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="label-caps text-[#69736c]">DAILY STATE TIME SERIES</p><p className="mt-2 text-sm text-[#657067]">Simulation {id.slice(0, 12)}… · {query.data.daily_states.length} daily records</p></div><div className="flex flex-wrap gap-2">{variables.map((key) => <button key={key} onClick={() => setVariable(key)} className={`px-3 py-2 text-[11px] ${variable === key ? 'bg-[#1b3022] text-white' : 'border border-[#dfe3dc]'}`}>{key.toUpperCase()}</button>)}</div></div><div className="mt-7 h-[340px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={data} margin={{ top: 10, right: 15, left: 0, bottom: 10 }}><CartesianGrid stroke="#e9ece5" vertical={false} /><XAxis dataKey="date" tick={{ fontSize: 10, fill: '#788078' }} tickLine={false} /><YAxis tick={{ fontSize: 10, fill: '#788078' }} tickLine={false} axisLine={false} /><Tooltip /><Line type="monotone" dataKey="value" stroke="#1b3022" strokeWidth={2} dot={false} /></LineChart></ResponsiveContainer></div></Panel><div className="mt-5 flex gap-3"><Link href={`/assimilation/${id}`} className="bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white">Open assimilation</Link><Link href={`/forecast/${id}`} className="border border-[#1b3022] px-4 py-3 text-xs font-semibold">Open forecast</Link></div></Page>;
}

function AssimilationPage({ id }: { id: string }) {
  const sim = useQuery({ queryKey: ['simulation', id], queryFn: () => api.simulation(id), ...queryOptions }); const status = useQuery({ queryKey: ['assimilation-status', id], queryFn: () => api.assimilationStatus(id), ...queryOptions }); const history = useQuery({ queryKey: ['assimilation-history', id], queryFn: () => api.assimilationHistory(id), ...queryOptions }); const series = useQuery({ queryKey: ['assimilation-series', id], queryFn: () => api.assimilationTimeseries(id), ...queryOptions }); const yieldEvolution = useQuery({ queryKey: ['yield-evolution', id], queryFn: () => api.yieldEvolution(id), ...queryOptions }); const diagnostics = useQuery({ queryKey: ['diagnostics', id], queryFn: () => api.assimilationDiagnostics(id), ...queryOptions }); const [variable, setVariable] = useState('LAI'); const [cycle, setCycle] = useState(0); const run = useMutation({ mutationFn: api.runAssimilation, onSuccess: () => { status.refetch(); history.refetch(); series.refetch(); diagnostics.refetch(); } });
  const chart = (series.data?.[variable] || []).map((point) => ({ ...point, date: point.date })); const selected = cycle >= 0 ? history.data?.[cycle] : undefined;
  if (status.isLoading) return <Page eyebrow="05 / ASSIMILATION" title="Loading assimilation"><Loading /></Page>;
  return <Page eyebrow="05 / ASSIMILATION DASHBOARD" title="Ensemble Kalman Filter" description="Sequentially updates the simulated crop state using observations and ensemble uncertainty."><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Metric label="Status" value={status.data?.status} /><Metric label="Ensemble size" value={status.data?.ensemble_size} /><Metric label="Cycles" value={`${status.data?.executed_cycles ?? '—'} / ${status.data?.total_cycles ?? '—'}`} /><Metric label="Skipped cycles" value={status.data?.skipped_cycles} /><Metric label="Observations" value={status.data?.observations_assimilated} /></div><Panel className="mt-5 p-5"><div className="flex flex-wrap justify-between gap-3"><div><p className="label-caps text-[#69736c]">ASSIMILATION TIME SERIES</p><p className="mt-2 text-xs text-[#788078]">Open loop, assimilated state, and observations returned by the backend.</p></div><div className="flex flex-wrap gap-2">{Object.keys(series.data || {}).map((key) => <button key={key} onClick={() => setVariable(key)} className={`px-3 py-2 text-[11px] ${variable === key ? 'bg-[#1b3022] text-white' : 'border border-[#dfe3dc]'}`}>{key}</button>)}</div></div>{series.isError ? <div className="mt-6"><StateMessage title="Unable to load assimilation time series." error={series.error as Error} onRetry={() => series.refetch()} /></div> : <div className="mt-6 h-[320px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={chart}><CartesianGrid stroke="#e9ece5" vertical={false} /><XAxis dataKey="date" tick={{ fontSize: 10 }} /><YAxis tick={{ fontSize: 10 }} /><Tooltip /><Line dataKey="open_loop" name="Open loop" stroke="#1b3022" dot={false} /><Line dataKey="assimilated" name="Assimilated" stroke="#8fa382" strokeDasharray="6 5" dot={false} /><Line dataKey="observation" name="Observation" stroke="#d97706" dot={{ r: 4 }} connectNulls={false} /></LineChart></ResponsiveContainer></div>}</Panel><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_1fr]"><Panel className="p-5"><div className="flex items-center justify-between"><p className="label-caps text-[#69736c]">CYCLE EXPLORER</p><select value={cycle} onChange={(e) => setCycle(Number(e.target.value))} className="border border-[#dfe3dc] bg-white px-2 py-2 text-xs"><option value={-1}>Select cycle</option>{history.data?.map((item, index) => <option key={item.cycle_number} value={index}>Cycle {item.cycle_number} · {item.cycle_date}</option>)}</select></div>{selected ? <div className="mt-5 grid grid-cols-2 gap-2">{[['PRIOR', selected.prior_state], ['OBSERVATION', selected.observation_vector], ['INNOVATION', selected.innovation], ['POSTERIOR', selected.posterior_state]].map(([label, values]) => <div key={String(label)} className="border border-[#e5e7df] p-3"><p className="label-caps text-[#69736c]">{String(label)}</p>{Object.entries(values as Record<string, number | null>).map(([key, value]) => <div key={key} className="mt-3 flex justify-between text-xs"><span>{key}</span><span className="mono">{value ?? '—'}</span></div>)}</div>)}</div> : <p className="mt-5 text-xs text-[#788078]">No assimilation history returned.</p>}</Panel><Panel className="p-5"><p className="label-caps text-[#69736c]">RUN ASSIMILATION</p><p className="mt-3 text-sm text-[#657067]">This calls the synchronous EnKF endpoint and may take time.</p><button disabled={run.isPending || !sim.data?.field_id} onClick={() => sim.data?.field_id && run.mutate({ simulation_id: id, field_id: sim.data.field_id, ensemble_size: status.data?.ensemble_size || 20 })} className="mt-5 bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white">{run.isPending ? 'Running EnKF…' : 'Run assimilation'}</button>{run.error && <p className="mt-3 text-xs text-[#a34f38]">{(run.error as Error).message}</p>}<div className="mt-6 border-t border-[#e5e7df] pt-5 text-xs"><p className="label-caps text-[#69736c]">YIELD EVOLUTION</p>{yieldEvolution.data?.length ? <p className="mt-3 mono">{yieldEvolution.data[yieldEvolution.data.length - 1].predicted_yield_kg_ha ?? '—'} kg/ha latest prediction</p> : <p className="mt-3 text-[#788078]">No yield evolution returned.</p>}</div>{diagnostics.data && <p className="mt-5 text-xs text-[#657067]">Valid observations: {diagnostics.data.total_valid_obs} · Rejected: {diagnostics.data.total_rejected_obs}</p>}</Panel></div></Page>;
}

function ObservationsPage() {
  const [filters, setFilters] = useState({ field_id: '', variable_name: '', source: '', status: '' }); const query = useQuery({ queryKey: ['observations', filters], queryFn: () => api.observations(filters), ...queryOptions }); const qc = useQueryClient(); const create = useMutation({ mutationFn: api.createObservation, onSuccess: () => qc.invalidateQueries({ queryKey: ['observations'] }) });
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); create.mutate({ field_id: d.get('field_id') || null, timestamp: new Date(String(d.get('timestamp'))).toISOString(), variable_name: d.get('variable_name'), units: d.get('units'), value: Number(d.get('value')), uncertainty: Number(d.get('uncertainty')), source: d.get('source'), provider_name: d.get('provider_name') }); };
  return <Page eyebrow="06 / OBSERVATIONS" title="Observation explorer" description="Source-aware observations with quality, uncertainty, provenance, and status preserved from the backend."><Panel className="p-5"><p className="label-caps text-[#69736c]">FILTERS</p><div className="mt-4 grid gap-2 sm:grid-cols-4">{Object.keys(filters).map((key) => <input key={key} value={filters[key as keyof typeof filters]} onChange={(e) => setFilters({ ...filters, [key]: e.target.value })} placeholder={key.replace('_', ' ')} className="border border-[#dfe3dc] px-3 py-2.5 text-xs" />)}</div></Panel><Panel className="mt-5 p-5"><p className="label-caps text-[#69736c]">REGISTER OBSERVATION</p><form onSubmit={submit} className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{[['field_id', 'Field ID (optional)'], ['timestamp', 'Timestamp'], ['variable_name', 'Variable'], ['units', 'Units'], ['value', 'Value'], ['uncertainty', 'Uncertainty'], ['provider_name', 'Provider']].map(([name, label]) => <label key={name} className="text-xs text-[#69736c]">{label}<input required={!name.includes('field')} name={name} type={name === 'timestamp' ? 'datetime-local' : name === 'value' || name === 'uncertainty' ? 'number' : 'text'} step="any" className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label>)}<label className="text-xs text-[#69736c]">Source<select name="source" className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option>SATELLITE</option><option>SENSOR</option><option>WEATHER</option><option>MANUAL</option><option>MODEL</option></select></label><button className="self-end bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white">{create.isPending ? 'Saving…' : 'Save observation'}</button></form>{create.error && <p className="mt-3 text-xs text-[#a34f38]">{(create.error as Error).message}</p>}</Panel>{query.isLoading ? <div className="mt-5"><Loading /></div> : query.isError ? <div className="mt-5"><StateMessage title="Unable to load observations." error={query.error as Error} onRetry={() => query.refetch()} /></div> : !query.data?.items.length ? <div className="mt-5"><StateMessage title="No valid observations found." /></div> : <Panel className="mt-5"><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left text-xs"><thead className="border-b border-[#dfe3dc] text-[#69736c]"><tr>{['Timestamp', 'Variable', 'Value', 'Uncertainty', 'Source', 'Provider', 'Quality', 'Status'].map((h) => <th key={h} className="px-4 py-4 font-medium">{h}</th>)}</tr></thead><tbody>{query.data.items.map((observation) => <tr key={observation.observation_id || observation.id || observation.timestamp} className="border-b border-[#eef0eb]"><td className="px-4 py-4">{formatDate(observation.timestamp)}</td><td className="px-4 py-4 font-semibold">{observation.variable_name}</td><td className="mono px-4 py-4">{observation.value} {observation.units}</td><td className="mono px-4 py-4">{observation.uncertainty}</td><td className="px-4 py-4">{observation.source}</td><td className="px-4 py-4">{observation.provider_name}</td><td className="px-4 py-4">{observation.quality_score ?? '—'}</td><td className="px-4 py-4">{observation.status ?? '—'}</td></tr>)}</tbody></table></div></Panel>}</Page>;
}

function SatellitePage() {
  const fields = useQuery({ queryKey: ['fields', 'satellite'], queryFn: () => api.fields(), ...queryOptions }); const [fieldId, setFieldId] = useState(''); const [result, setResult] = useState<Awaited<ReturnType<typeof api.satelliteLai>> | null>(null); const [error, setError] = useState(''); const [pending, setPending] = useState(false);
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setError(''); setPending(true); const d = new FormData(e.currentTarget); try { setResult(await api.satelliteLai({ field_id: fieldId, start_date: d.get('start_date') as string, end_date: d.get('end_date') as string, index_name: d.get('index_name') as string, max_cloud_cover: Number(d.get('max_cloud_cover')) })); } catch (err) { setError((err as Error).message); } finally { setPending(false); } };
  return <Page eyebrow="07 / SATELLITE OBSERVATIONS" title="Satellite LAI" description="Retrieve Sentinel-2 observations from the backend and keep their acquisition, quality, cloud cover, indices, and estimated LAI visible."><Panel className="p-5"><form onSubmit={submit} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><label className="text-xs text-[#69736c]">Field<select required value={fieldId} onChange={(e) => setFieldId(e.target.value)} className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option value="">Select field</option>{fields.data?.items.map((f) => <option key={f.field_id} value={f.field_id}>{f.name}</option>)}</select></label>{[['start_date', 'Start date'], ['end_date', 'End date']].map(([name, label]) => <label key={name} className="text-xs text-[#69736c]">{label}<input required name={name} type="date" className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label>)}<label className="text-xs text-[#69736c]">Vegetation index<select name="index_name" className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option>NDVI</option><option>OSAVI</option><option>SeLI</option></select></label><label className="text-xs text-[#69736c]">Max cloud cover<input name="max_cloud_cover" defaultValue="0.2" type="number" min="0" max="1" step="0.01" className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label><button disabled={pending} className="bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white sm:col-span-2 lg:col-span-5">{pending ? 'Retrieving observations…' : 'Retrieve satellite observations'}</button></form></Panel>{error && <div className="mt-5"><StateMessage title="Satellite request failed." error={new Error(error)} /></div>}{result && <Panel className="mt-5"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left text-xs"><thead className="border-b border-[#dfe3dc]"><tr>{['Acquisition', 'Cloud cover', 'NDVI', 'OSAVI', 'SeLI', 'Estimated LAI', 'Quality'].map((h) => <th key={h} className="px-4 py-4 font-medium">{h}</th>)}</tr></thead><tbody>{result.map((scene) => <tr key={scene.acquisition_date} className="border-b border-[#eef0eb]"><td className="px-4 py-4">{formatDate(scene.acquisition_date)}</td><td className="px-4 py-4">{scene.cloud_cover}</td><td className="mono px-4 py-4">{scene.ndvi ?? '—'}</td><td className="mono px-4 py-4">{scene.osavi ?? '—'}</td><td className="mono px-4 py-4">{scene.seli ?? '—'}</td><td className="mono px-4 py-4">{scene.estimated_lai ?? '—'}</td><td className="px-4 py-4">{scene.quality_score}</td></tr>)}</tbody></table></div></Panel>}</Page>;
}

function FusionPage() {
  const fields = useQuery({ queryKey: ['fields', 'fusion'], queryFn: () => api.fields(), ...queryOptions }); const [fieldId, setFieldId] = useState(''); const [result, setResult] = useState<Record<string, unknown> | null>(null); const [error, setError] = useState('');
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); try { setError(''); setResult(await api.fusion('pipeline', { field_id: fieldId, start_date: d.get('start_date'), end_date: d.get('end_date'), crop_type: d.get('crop_type') })); } catch (err) { setError((err as Error).message); } };
  return <Page eyebrow="08 / DATA FUSION" title="Fusion workspace" description="Run the complete validation → temporal alignment → spatial alignment → confidence → multi-source fusion pipeline explicitly."><Panel className="p-5"><div className="mb-5 flex flex-wrap gap-3 text-xs text-[#536056]">{['01 Temporal gap handling', '02 Spatial alignment', '03 Confidence / R estimation', '04 Multi-source fusion', '05 Unified observation stream'].map((step) => <span key={step} className="border border-[#dfe3dc] px-3 py-2">{step}</span>)}</div><form onSubmit={submit} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label className="text-xs text-[#69736c]">Field<select required value={fieldId} onChange={(e) => setFieldId(e.target.value)} className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option value="">Select field</option>{fields.data?.items.map((f) => <option key={f.field_id} value={f.field_id}>{f.name}</option>)}</select></label>{[['start_date', 'Start date'], ['end_date', 'End date'], ['crop_type', 'Crop type']].map(([name, label]) => <label key={name} className="text-xs text-[#69736c]">{label}<input required name={name} defaultValue={name === 'crop_type' ? 'wheat' : ''} type={name.includes('date') ? 'date' : 'text'} className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label>)}<button className="bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white sm:col-span-2 lg:col-span-4">Run full fusion pipeline</button></form></Panel>{error && <div className="mt-5"><StateMessage title="Fusion request failed." error={new Error(error)} /></div>}{result && <Panel className="mt-5 p-5"><p className="label-caps text-[#69736c]">PIPELINE RESULT</p><pre className="mt-4 overflow-auto whitespace-pre-wrap text-xs leading-5 text-[#536056]">{JSON.stringify(result, null, 2)}</pre></Panel>}</Page>;
}

function ScenariosPage() {
  const sims = useQuery({ queryKey: ['simulations', 'scenarios'], queryFn: () => api.simulations(), ...queryOptions }); const crops = useQuery({ queryKey: ['crops'], queryFn: api.crops, ...queryOptions }); const [result, setResult] = useState<Record<string, unknown> | null>(null); const [error, setError] = useState('');
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); try { setError(''); setResult(await api.scenario({ name: d.get('name'), generator_type: d.get('generator_type'), parameter_name: d.get('generator_type') === 'SOWING_DATE' ? 'sowing_date' : d.get('generator_type') === 'VARIETY' ? 'variety' : 'irrigation_events', parameter_values: String(d.get('parameter_values')).split(',').map((value) => value.trim()), base_simulation_id: d.get('base_simulation_id') || null })); } catch (err) { setError((err as Error).message); } };
  return <Page eyebrow="09 / SCENARIO ANALYSIS" title="Model scenarios" description="Explicit what-if runs against a base simulation. Scenario results are model outputs, not observations."><Panel className="p-5"><form onSubmit={submit} className="grid gap-3 sm:grid-cols-2"><label className="text-xs text-[#69736c]">Scenario name<input required name="name" className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label><label className="text-xs text-[#69736c]">Mode<select name="generator_type" className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option>SOWING_DATE</option><option>IRRIGATION</option><option>VARIETY</option></select></label><label className="text-xs text-[#69736c]">Base simulation<select name="base_simulation_id" className="mt-1 w-full border border-[#dfe3dc] bg-white px-3 py-2.5"><option value="">Select simulation</option>{sims.data?.items.map((sim) => <option key={sim.simulation_id} value={sim.simulation_id}>{sim.crop} · {sim.sowing_date}</option>)}</select></label><label className="text-xs text-[#69736c]">Candidate values<input required name="parameter_values" placeholder="2024-10-01, 2024-10-15" className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label><button className="bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white sm:col-span-2">Run scenario comparison</button></form>{crops.isError && <p className="mt-3 text-xs text-[#a34f38]">Crop catalog unavailable; variety choices cannot be populated.</p>}</Panel>{error && <div className="mt-5"><StateMessage title="Scenario request failed." error={new Error(error)} /></div>}{result && <Panel className="mt-5 p-5"><p className="label-caps text-[#69736c]">SCENARIO RESULT</p><pre className="mt-4 overflow-auto whitespace-pre-wrap text-xs leading-5">{JSON.stringify(result, null, 2)}</pre></Panel>}</Page>;
}

function BenchmarkPage() {
  const sims = useQuery({ queryKey: ['simulations', 'benchmark'], queryFn: () => api.simulations(), ...queryOptions }); const [result, setResult] = useState<Record<string, unknown> | null>(null); const [error, setError] = useState('');
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); try { setError(''); const points = JSON.parse(String(d.get('ground_truth'))); setResult(await api.benchmark({ simulation_id: d.get('simulation_id'), variable: d.get('variable'), ground_truth: points, confidence_level: 0.95 })); } catch (err) { setError((err as Error).message); } };
  return <Page eyebrow="10 / SCIENTIFIC VALIDATION" title="Benchmark" description="Compare open-loop and assimilated predictions against real external ground truth. Ground truth is supplied by the researcher; it is never manufactured by the client."><Panel className="p-5"><form onSubmit={submit} className="grid gap-3"><label className="text-xs text-[#69736c]">Simulation<select required name="simulation_id" className="mt-1 max-w-xl border border-[#dfe3dc] bg-white px-3 py-2.5"><option value="">Select simulation</option>{sims.data?.items.map((sim) => <option key={sim.simulation_id} value={sim.simulation_id}>{sim.crop} · {sim.sowing_date}</option>)}</select></label><label className="text-xs text-[#69736c]">Variable<select name="variable" className="mt-1 max-w-xl border border-[#dfe3dc] bg-white px-3 py-2.5"><option>LAI</option><option>SM</option><option>TAGP</option><option>TWSO</option></select></label><label className="text-xs text-[#69736c]">Ground truth JSON<input required name="ground_truth" placeholder='[{"date":"2024-01-10","variable":"LAI","value":1.2}]' className="mt-1 w-full border border-[#dfe3dc] px-3 py-2.5" /></label><button className="w-fit bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white">Evaluate benchmark</button></form></Panel>{error && <div className="mt-5"><StateMessage title="Benchmark request failed." error={new Error(error)} /></div>}{result && <Panel className="mt-5 p-5"><pre className="overflow-auto whitespace-pre-wrap text-xs leading-5">{JSON.stringify(result, null, 2)}</pre></Panel>}</Page>;
}

function ScoutPage() {
  const fields = useQuery({ queryKey: ['fields', 'scout'], queryFn: () => api.fields(), ...queryOptions }); const [fieldId, setFieldId] = useState(''); const [result, setResult] = useState<Record<string, unknown> | null>(null); const [error, setError] = useState('');
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const form = e.currentTarget; const input = form.elements.namedItem('images'); const images = input instanceof HTMLInputElement && input.files ? Array.from(input.files) : []; const d = new FormData(form); if (images.length !== 5) { setError('Exactly 5 images are required for the W-Shape protocol.'); return; } try { setError(''); setResult(await api.scout(fieldId, images, String(d.get('notes') || ''))); } catch (err) { setError((err as Error).message); } };
  return <Page eyebrow="11 / FIELD SCOUTING" title="W-Shape scout session" description="Experimental smartphone workflow. The current backend returns a pending status while GPS EXIF, GRVI, LAI, and observation creation remain in progress."><Panel className="border-[#d97706] p-5"><div className="flex items-start gap-3"><Sprout className="mt-0.5 text-[#d97706]" size={18} /><div><p className="label-caps text-[#a66a21]">EXPERIMENTAL / PIPELINE IN PROGRESS</p><p className="mt-2 text-xs leading-5 text-[#657067]">Upload exactly five images in a W pattern. This interface does not calculate GRVI or LAI in the frontend.</p></div></div><form onSubmit={submit} className="mt-6 grid gap-3"><label className="text-xs text-[#69736c]">Field<select required value={fieldId} onChange={(e) => setFieldId(e.target.value)} className="mt-1 max-w-md border border-[#dfe3dc] bg-white px-3 py-2.5"><option value="">Select field</option>{fields.data?.items.map((f) => <option key={f.field_id} value={f.field_id}>{f.name}</option>)}</select></label><label className="text-xs text-[#69736c]">Five field images<input required name="images" type="file" accept="image/*" multiple className="mt-1 block w-full max-w-md border border-[#dfe3dc] bg-white px-3 py-2.5 text-xs" /></label><label className="text-xs text-[#69736c]">Session notes<textarea name="notes" className="mt-1 block min-h-20 w-full border border-[#dfe3dc] px-3 py-2.5" /></label><button className="w-fit bg-[#1b3022] px-4 py-3 text-xs font-semibold text-white">Submit scout session</button></form></Panel>{error && <div className="mt-5"><StateMessage title="Scout session unavailable." error={new Error(error)} /></div>}{result && <Panel className="mt-5 p-5"><p className="label-caps text-[#69736c]">BACKEND RESPONSE</p><pre className="mt-4 overflow-auto whitespace-pre-wrap text-xs leading-5">{JSON.stringify(result, null, 2)}</pre></Panel>}</Page>;
}

function ForecastPage({ id }: { id: string }) {
  const query = useQuery({ queryKey: ['forecast', id], queryFn: () => api.forecast(id), ...queryOptions });
  const [variable, setVariable] = useState('LAI');
  const forecast = query.data as { trajectories?: Record<string, Array<{ date: string; mean: number; pi_lower_95: number; pi_upper_95: number; min_val: number; max_val: number }>>; yield_forecast?: { mean_yield_kg_ha: number; std_yield_kg_ha: number; pi_lower_95_kg_ha: number; pi_upper_95_kg_ha: number }; open_loop_result?: { mean_yield_kg_ha: number }; assimilated_result?: { mean_yield_kg_ha: number }; hybrid_result?: { corrected_yield_kg_ha: number } | null; forecast_mode?: string; confidence_explanation?: string } | undefined;
  const variables = Object.keys(forecast?.trajectories || {});
  const selected = forecast?.trajectories?.[variable] || forecast?.trajectories?.[variables[0] || ''] || [];
  const chart = selected.map((point) => ({ ...point, date: formatDate(point.date) }));
  if (query.isLoading) return <Page eyebrow="12 / FORECAST" title="Loading forecast"><Loading /></Page>;
  if (query.isError || !query.data || !forecast) return <Page eyebrow="12 / FORECAST" title="Forecast unavailable"><StateMessage title="Unable to load forecast." error={query.error as Error} onRetry={() => query.refetch()} /></Page>;
  return <Page eyebrow="12 / FORECAST" title="Forecast trajectories" description="Ensemble mean and prediction intervals returned by the backend. Forecast values are model outputs, not observations.">
    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">
      <Metric label="Open-loop yield" value={forecast.open_loop_result?.mean_yield_kg_ha} unit="kg/ha" />
      <Metric label="Assimilated yield" value={forecast.assimilated_result?.mean_yield_kg_ha} unit="kg/ha" />
      <Metric label="Forecast yield" value={forecast.yield_forecast?.mean_yield_kg_ha} unit="kg/ha" />
      <Metric label="Uncertainty" value={forecast.yield_forecast?.std_yield_kg_ha} unit="kg/ha standard deviation" />
      {forecast.hybrid_result && <Metric label="Hybrid yield" value={forecast.hybrid_result.corrected_yield_kg_ha} unit="kg/ha" />}
    </div>
    <Panel className="mt-5 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="label-caps text-[#69736c]">ENSEMBLE TRAJECTORY</p><p className="mt-2 text-xs text-[#788078]">{forecast.forecast_mode || 'Forecast'} · shaded area is the 95% prediction interval</p></div><div className="flex flex-wrap gap-2">{variables.map((key) => <button key={key} onClick={() => setVariable(key)} className={`px-3 py-2 text-[11px] ${variable === key ? 'bg-[#1b3022] text-white' : 'border border-[#dfe3dc]'}`}>{key}</button>)}</div></div><div className="mt-6 h-[360px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={chart}><CartesianGrid stroke="#e9ece5" vertical={false} /><XAxis dataKey="date" tick={{ fontSize: 10 }} /><YAxis tick={{ fontSize: 10 }} /><Tooltip /><Line dataKey="pi_upper_95" name="95% upper" stroke="#b7c8b5" dot={false} strokeDasharray="3 3" /><Line dataKey="mean" name="Ensemble mean" stroke="#1b3022" strokeWidth={2} dot={false} /><Line dataKey="pi_lower_95" name="95% lower" stroke="#b7c8b5" dot={false} strokeDasharray="3 3" /><Line dataKey="min_val" name="Minimum" stroke="#d7ddd4" dot={false} /><Line dataKey="max_val" name="Maximum" stroke="#d7ddd4" dot={false} /></LineChart></ResponsiveContainer></div></Panel>
    <div className="mt-5 grid gap-5 lg:grid-cols-2"><Panel className="p-5"><p className="label-caps text-[#69736c]">YIELD INTERVAL</p><div className="mt-5 grid grid-cols-2 gap-3 text-xs"><div><span className="text-[#69736c]">95% lower</span><p className="mono mt-2">{forecast.yield_forecast?.pi_lower_95_kg_ha} kg/ha</p></div><div><span className="text-[#69736c]">95% upper</span><p className="mono mt-2">{forecast.yield_forecast?.pi_upper_95_kg_ha} kg/ha</p></div></div></Panel><Panel className="p-5"><p className="label-caps text-[#69736c]">CONFIDENCE EXPLANATION</p><p className="mt-4 text-sm leading-6 text-[#536056]">{forecast.confidence_explanation || 'No confidence explanation returned.'}</p></Panel></div>
  </Page>;
}
function AboutPage() { return <Page eyebrow="13 / METHODOLOGY" title="About AgriTwin" description="AgriTwin combines WOFOST/PCSE crop simulation with observation quality control, data fusion, and Ensemble Kalman Filter assimilation."><div className="grid gap-5 md:grid-cols-3">{[['WOFOST / PCSE', 'Physics-based crop growth simulation with explicit agronomic state variables.'], ['Observations', 'Satellite, sensor, weather, manual, and model-derived records retain provenance and uncertainty.'], ['EnKF', 'Sequential state updates reconcile model forecasts with valid observations and ensemble spread.']].map(([title, text]) => <Panel key={title} className="p-6"><p className="label-caps text-[#6b866b]">{title}</p><p className="mt-6 text-sm leading-6 text-[#536056]">{text}</p></Panel>)}</div></Page>; }
function PlaceholderPage({ title, eyebrow, description }: { title: string; eyebrow: string; description: string }) { return <Page eyebrow={eyebrow} title={title} description={description}><StateMessage title="Select a simulation or field from the platform to begin." /></Page>; }

function Router() {
  const [fieldMatch, fieldParams] = useRoute<{ fieldId: string }>('/fields/:fieldId'); const [simMatch, simParams] = useRoute<{ simulationId: string }>('/simulations/:simulationId'); const [assimMatch, assimParams] = useRoute<{ simulationId: string }>('/assimilation/:simulationId'); const [forecastMatch, forecastParams] = useRoute<{ simulationId: string }>('/forecast/:simulationId');
  return <Switch><Route path="/" component={OverviewPage} /><Route path="/fields" component={FieldsPage} />{fieldMatch && fieldParams && <Route path="/fields/:fieldId"><FieldDetailPage id={fieldParams.fieldId} /></Route>}<Route path="/simulations" component={SimulationsPage} />{simMatch && simParams && <Route path="/simulations/:simulationId"><SimulationDetailPage id={simParams.simulationId} /></Route>}{assimMatch && assimParams && <Route path="/assimilation/:simulationId"><AssimilationPage id={assimParams.simulationId} /></Route>}<Route path="/observations" component={ObservationsPage} /><Route path="/satellite" component={SatellitePage} /><Route path="/fusion" component={FusionPage} /><Route path="/scenarios" component={ScenariosPage} /><Route path="/benchmark" component={BenchmarkPage} /><Route path="/scout" component={ScoutPage} /><Route path="/about" component={AboutPage} />{forecastMatch && forecastParams && <Route path="/forecast/:simulationId"><ForecastPage id={forecastParams.simulationId} /></Route>}<Route path="/forecast"><PlaceholderPage eyebrow="FORECAST" title="Forecast" description="Choose a simulation to inspect its ensemble forecast." /></Route><Route path="/assimilation"><PlaceholderPage eyebrow="ASSIMILATION" title="Assimilation" description="Open assimilation from a stored simulation." /></Route><Route component={() => <PlaceholderPage eyebrow="404 / NOT FOUND" title="Page not found" description="This route is not part of the AgriTwin platform." />} /></Switch>;
}
const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false, staleTime: 30_000 } } });
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={window.location.pathname}><Shell><Router /></Shell></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;